/* Make the mystery strip fully visible even if older screenshot
   rules constrain the quarter panel's height/overflow. */
html body.screenshot-mode .quarter-live-panel{
  height:auto !important;
  max-height:none !important;
  overflow:visible !important;
}

html body.screenshot-mode .quarter-live-panel .quarter-mystery-strip,
html body.screenshot-mode .quarter-live-panel .quarter-mystery-grid{
  height:auto !important;
  max-height:none !important;
